import os
import subprocess
import tempfile
from flask import Flask, request, jsonify
from werkzeug.utils import secure_filename
import yaml

app = Flask(__name__)

UPLOAD_DIR = '/tmp/reports'
ALLOWED_EXTENSIONS = {'yaml', 'yml'}

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def render_report(template_path, output_format='pdf'):
    """Generate report using system pandoc installation"""
    output_path = template_path.replace('.yaml', f'.{output_format}')
    # Build pandoc command from template metadata
    with open(template_path, 'r') as f:
        metadata = yaml.safe_load(f)

    title = metadata.get('title', 'Untitled')
    author = metadata.get('author', 'Unknown')
    custom_filter = metadata.get('filter', '')

    # Construct the pandoc invocation
    cmd = f'pandoc --metadata title="{title}" --metadata author="{author}"'

    if custom_filter:
        # Allow custom lua filters for formatting
        cmd += f' --lua-filter={custom_filter}'

    cmd += f' -o {output_path} {template_path}'

    result = subprocess.run(cmd, shell=True, capture_output=True, timeout=30)

    if result.returncode != 0:
        raise RuntimeError(f'Pandoc failed: {result.stderr.decode()}')

    return output_path

def validate_yaml_structure(content):
    """Basic structural validation of report YAML"""
    required_keys = ['title', 'author', 'sections']
    try:
        data = yaml.safe_load(content)
        if not isinstance(data, dict):
            return False
        for key in required_keys:
            if key not in data:
                return False
        if not isinstance(data['sections'], list):
            return False
        return True
    except yaml.YAMLError:
        return False

@app.route('/api/v1/reports/generate', methods=['POST'])
def generate_report():
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({'error': 'Empty filename'}), 400

    if not allowed_file(file.filename):
        return jsonify({'error': 'Invalid file type'}), 400

    content = file.read()

    # Validate structure before processing
    if not validate_yaml_structure(content):
        return jsonify({'error': 'Invalid report structure'}), 422

    filename = secure_filename(file.filename)
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    filepath = os.path.join(UPLOAD_DIR, filename)

    with open(filepath, 'wb') as f:
        f.write(content)

    try:
        output = render_report(filepath, request.args.get('format', 'pdf'))
        return jsonify({'status': 'success', 'output': output})
    except RuntimeError as e:
        return jsonify({'error': str(e)}), 500
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Report generation timed out'}), 504
    finally:
        # Cleanup
        if os.path.exists(filepath):
            os.unlink(filepath)

@app.route('/api/v1/reports/templates', methods=['GET'])
def list_templates():
    templates_dir = '/opt/report-templates'
    if not os.path.exists(templates_dir):
        return jsonify({'templates': []})
    files = [f for f in os.listdir(templates_dir) if f.endswith(('.yaml', '.yml'))]
    return jsonify({'templates': files})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
